Here's a complete implementation:

### XAML — `ItemsPage.xaml`

```xml
<ContentPage xmlns="http://schemas.microsoft.com/dotnet/2021/maui"
             xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"
             xmlns:models="clr-namespace:MyApp.Models"
             xmlns:vm="clr-namespace:MyApp.ViewModels"
             x:Class="MyApp.Views.ItemsPage"
             x:DataType="vm:ItemsViewModel">

    <RefreshView IsRefreshing="{Binding IsRefreshing}"
                 Command="{Binding RefreshCommand}">
        <CollectionView ItemsSource="{Binding Items}"
                        SelectionMode="Single"
                        SelectedItem="{Binding SelectedItem, Mode=TwoWay}"
                        SelectionChangedCommand="{Binding ItemSelectedCommand}">
            <CollectionView.ItemTemplate>
                <DataTemplate x:DataType="models:Item">
                    <Grid Padding="12" ColumnDefinitions="48,*">
                        <Image Source="{Binding Icon}" WidthRequest="40" HeightRequest="40" />
                        <VerticalStackLayout Grid.Column="1" VerticalOptions="Center">
                            <Label Text="{Binding Name}" FontAttributes="Bold" />
                            <Label Text="{Binding Description}" FontSize="12" TextColor="Gray" />
                        </VerticalStackLayout>
                    </Grid>
                </DataTemplate>
            </CollectionView.ItemTemplate>
            <CollectionView.EmptyView>
                <ContentView>
                    <Label Text="No items found."
                           HorizontalOptions="Center" VerticalOptions="Center" />
                </ContentView>
            </CollectionView.EmptyView>
        </CollectionView>
    </RefreshView>
</ContentPage>
```

### ViewModel — `ItemsViewModel.cs`

```csharp
using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;
using System.Collections.ObjectModel;

public partial class ItemsViewModel : ObservableObject
{
    private readonly IApiService _api;

    public ItemsViewModel(IApiService api)
    {
        _api = api;
    }

    public ObservableCollection<Item> Items { get; } = new();

    [ObservableProperty]
    private Item? _selectedItem;

    [ObservableProperty]
    private bool _isRefreshing;

    [RelayCommand]
    private async Task ItemSelected()
    {
        if (SelectedItem is null) return;

        var navParam = new Dictionary<string, object> { { "Item", SelectedItem } };
        await Shell.Current.GoToAsync("DetailPage", navParam);

        // Clear selection so the user can re-select the same item later
        SelectedItem = null;
    }

    [RelayCommand]
    private async Task Refresh()
    {
        try
        {
            var data = await _api.GetItemsAsync();
            MainThread.BeginInvokeOnMainThread(() =>
            {
                Items.Clear();
                foreach (var item in data)
                    Items.Add(item);
            });
        }
        finally
        {
            IsRefreshing = false;   // stops the spinner
        }
    }
}
```

### Key binding relationships

| XAML property | ViewModel property | Why |
|---|---|---|
| `RefreshView.IsRefreshing` | `IsRefreshing` (bool) | Two-way; set `false` when done to stop spinner |
| `RefreshView.Command` | `RefreshCommand` | Fires on pull-down; reloads from API |
| `CollectionView.ItemsSource` | `Items` (`ObservableCollection<T>`) | Auto-updates UI on add/remove |
| `CollectionView.SelectedItem` | `SelectedItem` (TwoWay) | Tracks the tapped item |
| `SelectionChangedCommand` | `ItemSelectedCommand` | Navigates to detail page, then clears selection |

### Important details

- **`ObservableCollection<T>`** — never use `List<T>`; swapping a list forces a full re-render.
- **`x:DataType`** on both the page and the `DataTemplate` enables compiled bindings.
- **Clear `SelectedItem`** after navigation so the same item can be tapped again.
- **Set `IsRefreshing = false`** in a `finally` block so the spinner always stops, even on error.
- **Update collections on the UI thread** via `MainThread.BeginInvokeOnMainThread`.
